export const formatIntl = (number) => {
  if (!number) return
  return new Intl.NumberFormat('id-ID').format(number)
}

export const getPlansAndTsiData = (plansAndBenefitsData) => {
  let counter = 0
  const nameToIdentifierMapper = {}
  const benefitGroups = plansAndBenefitsData.benefit_groups.map((benefitGroup, index) => ({
    name: benefitGroup.name,
    identifier: `benefitGroup${index}`,
    slug: benefitGroup.slug,
    benefits: benefitGroup.benefits.map((benefit, index) => {
      const benefitIdentifier = `benefit-${counter++}`
      nameToIdentifierMapper[`${benefitGroup.name}${benefit}`] = benefitIdentifier
      return { name: benefit, identifier: benefitIdentifier }
    })
  }))
  const tncs = {}
  for (const benefitGroup of plansAndBenefitsData.benefit_groups) {
    tncs[benefitGroup.name] = benefitGroup.tnc
  }

  const plansData = {}
  for (let i = 0; i < plansAndBenefitsData.benefit_groups.length; i++) {
    const benefitGroup = plansAndBenefitsData.benefit_groups[i]
    plansData[`benefitGroup${i}`] = [{ limit_type: benefitGroup.limit_type }]
    for (const plan of benefitGroup.plans) {
      const planData = { name: plan.name, 'Yearly Limit': formatIntl(String(plan.yearly_limit || '')), id: plan.id }
      for (let j = 0; j < plan.benefits.length; j++) {
        const benefit = plan.benefits[j]
        if (benefitGroup.slug === 'asuransi-jiwa') {
          planData[nameToIdentifierMapper[`${benefitGroup.name}${benefit.name}`]] = benefit.tsi_period ? `${benefit.tsi_amount}/${benefit.tsi_period}` : benefit.tsi_amount
        } else {
          planData[nameToIdentifierMapper[`${benefitGroup.name}${benefit.name}`]] = benefit.tsi_period ? `${formatIntl(benefit.tsi_amount)}/${benefit.tsi_period}` : formatIntl(String(benefit.tsi_amount || ''))
        }
      }
      plansData[`benefitGroup${i}`].push(planData)
    }
  }
  return { benefitGroups, tncs, plansData, isTsiLimitEditable: plansAndBenefitsData.is_tsi_limit_editable }
}

export const totalPremiumValidator = [
  {
    required: true,
    message: 'Total premium is required'
  },
  {
    pattern: /^-{0,1}\d+(\.\d+)*$/,
    message: 'Invalid format. Allowed formats is 5.000.500'
  },
  {
    validator: (_, value) => {
      if (!value) {
        return Promise.reject(new Error('Total premium is required'))
      }
      value = String(value).replace(/\./g, '')
      const valueAsNumber = Number(value)
      if (valueAsNumber > 0) {
        if (value.length > 9) {
          return Promise.reject(new Error('Number cannot have more than 9 digits before decimal'))
        }
      } else if (valueAsNumber <= 0) {
        return Promise.reject(new Error('Total premium should be greater than 0'))
      }
      return Promise.resolve()
    }
  }
]
