import { ApiContextProvider } from '@pasarpolis/common-react-hooks'
import React from 'react'
import { EBContextProvider } from '../../context'
import reducer from '../../state/Products/reducer'
import ProductDetailContainer from './containers'

function ProductDetail (props) {
  return (
    <EBContextProvider reducer={reducer} pageName='Product Detail'>
      <ApiContextProvider>
        <ProductDetailContainer {...props} />
      </ApiContextProvider>
    </EBContextProvider>
  )
}

export default ProductDetail
