/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useRef, useState } from 'react'
import { Button, Form, Empty, Spin, Alert, message, Col } from 'antd'
import { EditorState } from 'draft-js'
import BenefitPlansAndTSI from '../../AddProductV2/components/benefitPlansAndTSI'
import { getPlansAndTsiData } from './utility'
import { stateToHTML } from 'draft-js-export-html'
import { stateFromHTML } from 'draft-js-import-html'
import { useParams } from 'react-router'
import { useProductsContext } from '../../../state/Products/hooks/useProductsContext'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import ExportExcel from '../../../components/ExportExcel'
import ebUrls from '../../../../../../request/urls/employeeBenefit'
import { RowWithMargin } from '../../../CommonComponents/index.style'

const VIEW = 'view'
const EDIT = 'edit'

const getInitialEditorsState = (benefitGroups, storedData) => {
  const state = {}
  for (const benefitGroup of benefitGroups) {
    if (storedData && storedData[benefitGroup.name]) {
      state[benefitGroup.name] = EditorState.push(EditorState.createEmpty(), stateFromHTML(storedData[benefitGroup.name]))
    } else {
      state[benefitGroup.name] = EditorState.createEmpty()
    }
  }
  return state
}

const BenefitsAndPlansDetails = ({ form, next, prev }) => {
  const [{ benefitGroups, tncs, isTsiLimitEditable }, setPlansAndTsiData] = useState({})
  const [editorsState, setEditorsState] = useState(null)
  const plansData = useRef(null)
  const { getProductPlans, productPlansData, updateProductPlansRequest } = useProductsContext()
  const [{ PRODUCT_PLANS_LOADER, UPDATE_PRODUCT_PLANS_LOADER }] = useLoaderContextValue()
  const [{ PRODUCT_PLANS_ERROR, productPlansStatus, UPDATE_PRODUCT_PLANS_ERROR, updateProductPlansStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  const [mode, setMode] = useState(VIEW)
  const params = useParams()

  const handleSubmit = () => {
    form.validateFields((err, values) => {
      if (!err) {
        const toBeSendValues = { product_id: params.productId }
        if (toBeSendValues) {
          for (const key in values) {
            if (Array.isArray(values[key])) {
              values[key] = values[key].filter(item => !!item)
            }
          }
          const plansData = values
          toBeSendValues.benefit_groups = benefitGroups.map(({ benefits, name, identifier, slug }) => {
            const benefitGroup = { name, slug } // TODO: Remove slug from here if slug is not to be sent
            benefitGroup.tnc = stateToHTML(editorsState[name].getCurrentContent())
            benefitGroup.limit_type = plansData[identifier][0].limit_type
            // benefitGroup.plans = plansData
            let benefitGroupPlans = plansData[identifier].slice(1)
            benefitGroupPlans = benefitGroupPlans.map(({ name, 'Yearly Limit': yearlyLimit, id = null, ...plan }) => {
              const planObj = { name, yearly_limit: (yearlyLimit && String(yearlyLimit).replace(/\./g, '')) || null, id, benefits: [] }
              for (const { name, identifier } of benefits) {
                const tsiValue = plan[identifier]
                if (slug === 'asuransi-jiwa') {
                  planObj.benefits.push({ name, tsi: tsiValue || null })
                } else {
                  planObj.benefits.push({ name, tsi: (tsiValue && String(tsiValue).replace(/\./g, '')) || null })
                }
              }
              return planObj
            })
            benefitGroup.plans = benefitGroupPlans
            return benefitGroup
          })
        } else {
          // TODO: // display something went wrong.
        }
        updateProductPlansRequest(toBeSendValues)
      }
    })
  }

  const setEditorsStateByName = (name) => {
    return (changedState) => setEditorsState(state => ({
      ...state,
      [name]: changedState
    }))
  }

  useEffect(() => {
    if (productPlansData) {
      const { plansData: plans, benefitGroups, tncs, isTsiLimitEditable } = getPlansAndTsiData(productPlansData)
      setPlansAndTsiData({ benefitGroups, tncs, isTsiLimitEditable })
      setEditorsState(getInitialEditorsState(benefitGroups, tncs))
      plansData.current = plans
    }
  }, [productPlansData])

  useEffect(() => {
    if (updateProductPlansStatus === 'success') {
      message.success('Product Updated Successfully')
      getProductPlans({ product_id: params.productId })
      setMode(VIEW)
      resetError(['updateProductPlansStatus', 'UPDATE_PRODUCT_PLANS_ERROR'])
    }
  }, [updateProductPlansStatus])

  useEffect(() => {
    getProductPlans({ product_id: params.productId })
  }, [])

  return (
    <Spin spinning={!!PRODUCT_PLANS_LOADER || !!UPDATE_PRODUCT_PLANS_LOADER}>
      {PRODUCT_PLANS_ERROR && <Alert type='error' message={productPlansStatus} banner />}
      {UPDATE_PRODUCT_PLANS_ERROR && <Alert type='error' message={updateProductPlansStatus} banner />}
      <div className='description-title'>
        <RowWithMargin type='flex' gutter={32}>
          <Col>
            <h2>Benefit Group</h2>
          </Col>
          <Col>
            <ExportExcel
              buttonContent='Export Benefit Group Data'
              url={ebUrls.downloadBenefitGroupData}
              queryParams={{ product_id: params.productId }}
            />
          </Col>
        </RowWithMargin>
        {
          mode === VIEW
            ? (
              <Button
                type='ghost'
                onClick={() => setMode(EDIT)}
              >
                Edit
              </Button>
              )
            : (
              <Button
                type='ghost'
                onClick={() => setMode(VIEW)}
              >
                Cancel
              </Button>
              )
        }
      </div>
      {
        benefitGroups
          ? benefitGroups.map(({ name, identifier, benefits, slug }) => (
            <BenefitPlansAndTSI
              key={name + mode + JSON.stringify(plansData)}
              getFieldDecorator={form.getFieldDecorator}
              benefitGroupName={name}
              benefitGroupIdentifier={identifier}
              benefits={benefits}
              plansData={plansData.current[identifier]}
              form={form}
              editorsState={editorsState[name]}
              setEditorsState={setEditorsStateByName(name)}
              errors={form.getFieldError(name)}
              tnc={tncs[name]}
              mode={mode}
              isTsiLimitEditable={isTsiLimitEditable}
              benefitGroupSlug={slug}
            />
            ))
          : <Empty />
      }
      {
        mode === EDIT && (
          <div className='update-btn-container mt-5'>
            <Button
              type='primary'
              onClick={handleSubmit}
            >
              Update
            </Button>
          </div>
        )
      }
    </Spin>
  )
}
export default Form.create('product-benefit-groups-edit-form')(BenefitsAndPlansDetails)
