/* eslint-disable react-hooks/exhaustive-deps */
import React, { useCallback, useEffect, useState } from 'react'
import { Row, Col, Button, Spin, Empty, Form, Input, InputNumber, Select, Alert, message } from 'antd'
import { useProductsContext } from '../../../state/Products/hooks/useProductsContext'
import { useErrorContextValue, useGet, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useParams } from 'react-router'
import { totalPremiumValidator, formatIntl } from './utility'
import { RowWithMargin } from '../../../CommonComponents'
import { ProductContainer } from './index.style'
import { formatIntlCurrency } from '../../../../../../helpers/utility'
import { productsApiConfig } from '../../../state/Products/apiConfig'
import moment from 'moment-timezone'

// getPlansAndTsiData()

const VIEW = 'view'
const EDIT = 'edit'
const { Option } = Select
const formItemLayout = {
  labelCol: { span: 12 },
  wrapperCol: { span: 12 }
}

const claimTypeDisplayValue = {
  cashless: 'Cashless',
  reimbursement: 'Reimbursement',
  'cashless & reimbursement': 'Both'
}

const ProductGeneralInfo = ({ form, ...props }) => {
  const [mode, setMode] = useState(VIEW)
  const { getFieldDecorator } = form
  const { getProductDetail, productDetailData, updateProductInfoRequest } = useProductsContext()
  const [{ PRODUCT_DETAIL_LOADER, UPDATE_PRODUCT_INFO_LOADER }] = useLoaderContextValue()
  const [{ PRODUCT_DETAIL_ERROR, productDetailStatus, UPDATE_PRODUCT_INFO_ERROR, updateProductInfoStatus }] = useErrorContextValue()
  const params = useParams()
  const { resetError } = useResetError()
  const [hospitalProvidersListData, hospitalProvidersRequest] = useGet(productsApiConfig.getHospitalProviders)

  const getHospitalProviderDisplayName = useCallback((hospitalProvider) => {
    const hospitalProviderData = hospitalProvidersListData?.hospital_providers?.find(data => data.main_key === hospitalProvider)
    if (!hospitalProviderData) return hospitalProvider
    return hospitalProviderData.display_name
  }, [hospitalProvidersListData])

  const handleUpdate = () => {
    form.validateFields((err, values) => {
      if (!err) {
        resetError(['updateProductInfoStatus', 'UPDATE_PRODUCT_INFO_ERROR'])
        updateProductInfoRequest({
          ...values,
          total_premium: String(values.total_premium).replace(/\./g, ''),
          product_id: params.productId,
          reimbursement_percentage: values.reimbursement_percentage || null
        })
      }
    })
  }

  useEffect(() => {
    getProductDetail({ product_id: params.productId })
    hospitalProvidersRequest()
  }, [])

  useEffect(() => {
    if (updateProductInfoStatus === 'success') {
      setMode(VIEW)
      message.success('Product info updated successfully')
      getProductDetail({ product_id: params.productId })
      resetError([
        'updateProductInfoStatus'
      ])
    }
  }, [updateProductInfoStatus])

  const productData = productDetailData

  const title = (
    <div className='description-title'>
      <h2>Product Info</h2>
      {
        mode === VIEW
          ? (
            <Button
              type='ghost'
              onClick={() => setMode(EDIT)}
            >
              Edit
            </Button>
            )
          : (
            <Button
              type='ghost'
              onClick={() => setMode(VIEW)}
            >
              Cancel
            </Button>
            )
      }
    </div>
  )
  return (
    <Spin spinning={!!PRODUCT_DETAIL_LOADER || !!UPDATE_PRODUCT_INFO_LOADER}>
      {PRODUCT_DETAIL_ERROR && <Alert type='error' message={productDetailStatus} banner />}
      {UPDATE_PRODUCT_INFO_ERROR && <Alert type='error' message={updateProductInfoStatus} banner />}
      <div className='content'>
        {
          productData
            ? (
              <ProductContainer>
                {title}
                <RowWithMargin gutter={16}>
                  <Col span={12}>
                    <Row>
                      <Col span={12} className='label'>Product Id</Col>
                      <Col span={12} className='description'>{productData._packageID}</Col>
                    </Row>
                  </Col>
                  <Col span={12}>
                    <Row>
                      <Col span={12} className='label'>Created At</Col>
                      <Col span={12} className='description'>
                        {moment(productData?.created_at).format('DD-MM-YYYY')}
                      </Col>
                    </Row>
                  </Col>
                </RowWithMargin>
                <RowWithMargin gutter={16}>
                  <Col span={12}>
                    <Row>
                      <Col span={12} className='label'>Total GWP Collected</Col>
                      <Col span={12} className='description'>
                        {productData.total_gwp_collected ? formatIntl(productData.total_gwp_collected) : '-'}
                      </Col>
                    </Row>
                  </Col>
                  <Col span={12}>
                    <Row>
                      <Col span={12} className='label'>Insurance Provider</Col>
                      <Col span={12} className='description'>{productData.insurance_provider}</Col>
                    </Row>
                  </Col>
                </RowWithMargin>
                <RowWithMargin>
                  <Col span={12}>
                    <Row>
                      <Col span={12} className='label'>Coverage End Date</Col>
                      <Col span={12} className='description'>{ moment(productData?.coverage_end_date).format('DD-MM-YYYY')}</Col>
                    </Row>
                  </Col>
                </RowWithMargin>
                {
                  mode === VIEW && (
                    <>
                      <RowWithMargin gutter={16}>
                        <Col span={12}>
                          <Row>
                            <Col span={12} className='label'>Total Premium/Year</Col>
                            <Col span={12} className='description'>{formatIntlCurrency(productData.total_premium)}</Col>
                          </Row>
                        </Col>
                        <Col span={12}>
                          <Row>
                            <Col span={12} className='label'>Claim Type</Col>
                            <Col span={12} className='description capitalize'>{claimTypeDisplayValue[productData.claim_type]}</Col>
                          </Row>
                        </Col>
                      </RowWithMargin>
                      <RowWithMargin gutter={16}>
                        {
                          productData.claim_type !== 'cashless' && (
                            <Col span={12}>
                              <Row>
                                <Col span={12} className='label'>
                                  Reimbursement %
                                </Col>
                                <Col span={12} className='description'>
                                  {productData.reimbursement_percentage}
                                </Col>
                              </Row>
                            </Col>
                          )
                        }
                        <Col span={12}>
                          <Row>
                            <Col span={12} className='label'>Hospital Provider</Col>
                            <Col span={12} className='description'>{getHospitalProviderDisplayName(productData.hospital_provider)}</Col>
                          </Row>
                        </Col>
                      </RowWithMargin>
                    </>
                  )
                }
                {
                  mode === EDIT && (
                    <RowWithMargin gutter={16}>
                      <Form layout='horizontal'>
                        <Col span={12}>
                          <Form.Item
                            hasFeedback
                            label='Total Premium'
                            {...formItemLayout}
                            labelAlign='left'
                          >
                            {
                              getFieldDecorator('total_premium', {
                                initialValue: formatIntl(productData.total_premium),
                                rules: totalPremiumValidator
                              })(
                                <Input
                                  className='width-150'
                                />
                              )
                            }
                          </Form.Item>
                        </Col>
                        <Col span={12}>
                          <Form.Item
                            hasFeedback
                            label='Claim Type'
                            {...formItemLayout}
                            labelAlign='left'
                          >
                            {
                              getFieldDecorator('claim_type', {
                                initialValue: productData.claim_type
                              })(
                                <Select
                                  className='width-150'
                                  onBlur={() => form.validateFields()}
                                >
                                  <Option key='cashless' value='cashless'>Cashless</Option>
                                  <Option key='reimbursement' value='reimbursement'>Reimbursement</Option>
                                  <Option key='both' value='cashless & reimbursement'>Both</Option>
                                </Select>
                              )
                            }
                          </Form.Item>
                        </Col>
                        {
                          form.getFieldValue('claim_type') !== 'cashless' && (
                            <Col span={12}>
                              <Form.Item
                                hasFeedback
                                label='Reimbursement Percentage'
                                {...formItemLayout}
                                labelAlign='left'
                              >
                                {
                                  getFieldDecorator('reimbursement_percentage', {
                                    validateTrigger: 'onBlur',
                                    initialValue: productData.reimbursement_percentage,
                                    rules: [
                                      {
                                        required: ['reimbursement', 'cashless & reimbursement'].includes(form.getFieldValue('claim_type')),
                                        message: 'Reimbursement % is required'
                                      },
                                      {
                                        validator: (_, value) => {
                                          if (!value) {
                                            return Promise.resolve()
                                          }
                                          const valueInNumber = Number(value)
                                          return Number.isInteger(valueInNumber) && valueInNumber <= 100 && valueInNumber >= 1 ? Promise.resolve() : Promise.reject(new Error('Reimbursement % should be an integer value between 1 and 100'))
                                        }
                                      }
                                    ]
                                  })(
                                    <InputNumber
                                      className='width-150'
                                    />
                                  )
                                  }
                              </Form.Item>
                            </Col>
                          )
                        }
                        <Col span={12}>
                          <Form.Item
                            label='Hospital Provider'
                            {...formItemLayout}
                            labelAlign='left'
                          >
                            {getFieldDecorator('hospital_provider', {
                              initialValue: productData?.hospital_provider,
                              rules: [
                                { required: true, message: 'Hospital provider is required' }
                              ]
                            })(
                              <Select
                                className='width-150'
                              >
                                {
                                  Array.isArray(hospitalProvidersListData?.hospital_providers) && hospitalProvidersListData.hospital_providers
                                    .map(({ display_name: displayName, main_key: mainKey }) => (
                                      <Option
                                        key={mainKey}
                                        value={mainKey}
                                      >
                                        {displayName}
                                      </Option>
                                    ))
                                }
                              </Select>
                            )}
                          </Form.Item>
                        </Col>
                      </Form>
                    </RowWithMargin>
                  )
                }
                {
                  mode === EDIT && (
                    <div className='update-btn-container'>
                      <Button
                        type='primary'
                        onClick={handleUpdate}
                      >
                        Update
                      </Button>
                    </div>
                  )
                }
              </ProductContainer>
              )
            : <Empty />
        }
      </div>
    </Spin>
  )
}
export default Form.create({ name: 'edit-product-general-info' })(ProductGeneralInfo)
